<script setup>
import { ref, onBeforeUnmount } from 'vue'
import { useEditor, EditorContent } from '@tiptap/vue-3'
import StarterKit from '@tiptap/starter-kit'
import Image from '@tiptap/extension-image'
import { ElTooltip, ElMessage, ElMessageBox } from 'element-plus'
import { IconBold, IconItalic, IconH2, IconList, IconListNumbers, IconBlockquote, IconLink, IconPhoto, IconArrowBackUp, IconArrowForwardUp } from '@tabler/icons-vue'
import '../css/note-editor.css'
const props=defineProps({modelValue:String,text:String})
const emit=defineEmits(['update:modelValue','update:text','busy'])
const input=ref(null),pending=ref(0)
let disposed=false
const initial=props.modelValue||{type:'doc',content:(props.text||'').split('\n').map(line=>({type:'paragraph',...(line?{content:[{type:'text',text:line}]}:{})}))}
const editor=useEditor({content:initial,extensions:[StarterKit.configure({link:{openOnClick:false}}),Image.configure({allowBase64:true})],editorProps:{attributes:{role:'textbox','aria-label':'笔记正文','aria-multiline':'true'},handlePaste(view,event){const files=[...(event.clipboardData?.files||[])].filter(f=>f.type.startsWith('image/'));if(!files.length)return false;event.preventDefault();insertFiles(files);return true},handleDrop(view,event){const files=[...(event.dataTransfer?.files||[])].filter(f=>f.type.startsWith('image/'));if(!files.length)return false;event.preventDefault();const pos=view.posAtCoords({left:event.clientX,top:event.clientY});if(pos)editor.value.commands.setTextSelection(pos.pos);insertFiles(files);return true}},onUpdate:({editor})=>{emit('update:modelValue',editor.getHTML());emit('update:text',editor.getText())}})
async function insertFiles(files){for(const file of files){if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>2*1024*1024){ElMessage.error('图片需为 2MB 以内的 PNG、JPG 或 WebP');continue}pending.value++;emit('busy',true);try{const src=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file)});if(!disposed)editor.value.chain().focus().setImage({src,alt:file.name}).run()}catch{ElMessage.error('图片读取失败')}finally{pending.value--;if(!disposed)emit('busy',pending.value>0)}}}
function upload(e){insertFiles([...e.target.files]);e.target.value=''}
async function link(){try{const {value}=await ElMessageBox.prompt('输入链接地址，留空可移除链接','插入链接',{inputValue:editor.value.getAttributes('link').href||'',inputPlaceholder:'https://',inputValidator:v=>!v||/^https?:\/\/\S+$/i.test(v)||'请输入 HTTP 或 HTTPS 链接'});const chain=editor.value.chain().focus().extendMarkRange('link');value?chain.setLink({href:value.trim()}).run():chain.unsetLink().run()}catch{}}
const tools=[['加粗',IconBold,'bold',e=>e.chain().focus().toggleBold().run()],['斜体',IconItalic,'italic',e=>e.chain().focus().toggleItalic().run()],['标题',IconH2,'heading',e=>e.chain().focus().toggleHeading({level:2}).run()],['项目列表',IconList,'bulletList',e=>e.chain().focus().toggleBulletList().run()],['编号列表',IconListNumbers,'orderedList',e=>e.chain().focus().toggleOrderedList().run()],['引用',IconBlockquote,'blockquote',e=>e.chain().focus().toggleBlockquote().run()]]
onBeforeUnmount(()=>{disposed=true;editor.value?.destroy()})
</script>
<template><div class="note-editor"><div v-if="editor" class="note-editor-toolbar" role="toolbar" aria-label="正文格式"><ElTooltip v-for="t in tools" :key="t[0]" :content="t[0]" :show-after="200"><button type="button" :aria-label="t[0]" :aria-pressed="editor.isActive(t[2])" :class="{active:editor.isActive(t[2])}" @click="t[3](editor)"><component :is="t[1]" :size="18"/></button></ElTooltip><ElTooltip content="链接"><button type="button" aria-label="插入链接" @click="link"><IconLink :size="18"/></button></ElTooltip><ElTooltip content="图片（也可直接粘贴）"><button type="button" aria-label="插入正文图片" :disabled="pending>0" @click="input.click()"><IconPhoto :size="18"/></button></ElTooltip><ElTooltip content="撤销"><button type="button" aria-label="撤销" :disabled="!editor.can().undo()" @click="editor.chain().focus().undo().run()"><IconArrowBackUp :size="18"/></button></ElTooltip><ElTooltip content="重做"><button type="button" aria-label="重做" :disabled="!editor.can().redo()" @click="editor.chain().focus().redo().run()"><IconArrowForwardUp :size="18"/></button></ElTooltip></div><EditorContent :editor="editor"/><input ref="input" hidden type="file" accept="image/png,image/jpeg,image/webp" multiple @change="upload"/><div class="note-editor-hint">{{pending?'正在插入图片…':'支持粘贴或拖入图片 · 每张最大 2MB'}}</div></div></template>
